import{_ as t,a,c as i,ac as r}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"思考与方法：分析框架、定义与证据边界","description":"解释SWOT四维、把分类转为行动，并用讨论方案评分检查权重敏感性。","frontmatter":{"title":"思考与方法：分析框架、定义与证据边界","description":"解释SWOT四维、把分类转为行动，并用讨论方案评分检查权重敏感性。","showdocs":{"topics":[{"id":"thinking","title":"思考与方法","link":"/topics/thinking/"}],"kind":"框架及面试复习材料","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"思考与方法：把问题写成可检验判断","summary":"解释SWOT四维、把分类转为行动，并用讨论方案评分检查权重敏感性。","status":"active","related":[{"title":"思考与方法：把问题写成可检验判断","link":"/life/thinking/analysis/methods","kind":"问题与证据方法","scope":"general","audience":"general"},{"title":"思考与方法：复盘记录与行动收敛","link":"/life/thinking/retrospective/retrospective","kind":"偏差与后续行动","scope":"general","audience":"general"},{"title":"思考与方法：一次虚构讨论改进案例","link":"/life/thinking/reference/case-study","kind":"案例推演与复盘","scope":"general","audience":"general"}],"prev":{"text":"思考与方法：一次虚构讨论改进案例","link":"/life/thinking/reference/case-study"},"next":{"text":"思考与方法：复盘记录与行动收敛","link":"/life/thinking/retrospective/retrospective"}},"hashRedirects":{},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"思考与方法：一次虚构讨论改进案例","link":"/life/thinking/reference/case-study"},"next":{"text":"思考与方法：复盘记录与行动收敛","link":"/life/thinking/retrospective/retrospective"}},"headers":[],"relativePath":"life/thinking/analysis/frameworks.md","filePath":"life/thinking/analysis/frameworks.md"}'),n={name:"life/thinking/analysis/frameworks.md"};function s(l,e,d,o,p,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="思考与方法-框架与证据的边界" tabindex="-1">思考与方法：分析框架、定义与证据边界 <a class="header-anchor" href="#思考与方法-框架与证据的边界" aria-label="Permalink to &quot;思考与方法：分析框架、定义与证据边界 {#思考与方法-框架与证据的边界}&quot;">​</a></h1><p>先能区分观察与解释，再使用本页的SWOT分类和权重比较。评分中的A/B沿用<a href="/life/thinking/reference/case-study#decision">讨论方案定义</a>：A保留六题自由发言，B选两题轮流发言。例子为原创教学材料，不代表用户事实。</p><h2 id="part-2" tabindex="-1">SWOT 的四个维度 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;SWOT 的四个维度 {#part-2}&quot;">​</a></h2><p><span id="part-2-产品分析"></span></p><p><span id="part-2-介绍"></span></p><p>SWOT 用于把研究对象的内部条件与外部环境放在同一框架中比较：</p><table tabindex="0"><thead><tr><th>维度</th><th>含义</th></tr></thead><tbody><tr><td>S — Strengths</td><td>内部优势</td></tr><tr><td>W — Weaknesses</td><td>内部劣势</td></tr><tr><td>O — Opportunities</td><td>外部机会</td></tr><tr><td>T — Threats</td><td>外部威胁</td></tr></tbody></table><p>先列出调查得到的因素，再比较优势如何把握机会、劣势会放大哪些威胁，从而形成发展策略、计划或待验证问题。</p><h2 id="swot" tabindex="-1">SWOT转成问题 <a class="header-anchor" href="#swot" aria-label="Permalink to &quot;SWOT转成问题 {#swot}&quot;">​</a></h2><p>思考 SWOT转成问题时，内部优势劣势与外部机会威胁不能混列。虚构小组的优势是已有两位愿意轮流主持，劣势是准备时间少；机会是图书馆提供免费讨论室，威胁是预约时间冲突。分类本身不会自动生成正确策略。</p><p>由优势加机会提出“轮值主持利用固定场地”；由劣势加威胁提出“准备一份可缩短的问题单”。每条策略还需负责人、时点、验证证据。结合<a href="#part-2">四个维度</a>检查分类，再把清单转成待验证的行动。</p><h2 id="weights" tabindex="-1">权重与敏感性 <a class="header-anchor" href="#weights" aria-label="Permalink to &quot;权重与敏感性 {#weights}&quot;">​</a></h2><p>思考 权重与敏感性用于暴露判断，而不是把主观评分包装成事实。A在参与和覆盖得分为2、5，B为4、3；权重各一半时A=3.5、B=3.5。参与权重0.7时A=2.9、B=3.7，排序改变。</p><p>题：参与权重w时何时B优于A？B分为4w+3(1-w)=3+w，A分为2w+5(1-w)=5-3w；B大于A当4w&gt;2，即w&gt;0.5。若无法解释评分依据，应先收集证据，不靠加小数位制造精确感。</p><h2 id="interview" tabindex="-1">面试复习活动 <a class="header-anchor" href="#interview" aria-label="Permalink to &quot;面试复习活动 {#interview}&quot;">​</a></h2><p>思考 面试复习活动把旧题当检索练习：先闭卷回答、标明版本前提、给反例，再到对应技术正文核对。自评分为“能复述”“能解释条件”“能举反例”，不能用背过题数推断真实项目经验。</p>',16)])])}const f=t(n,[["render",s]]);export{k as __pageData,f as default};
